class DrawableFormat:
  DRAWABLE_FORMAT_RGBA8 = 0
  DRAWABLE_FORMAT_RGBA8_SRGB = 1
  DRAWABLE_FORMAT_RGBAH = 2
  DRAWABLE_FORMAT_RGBAF = 3


class DrawableTexture2D(py4godot_texture2d.Texture2D):
  r'''
		A 2D texture that can be modified via blit calls, copying from a target texture to itself. Primarily intended to be managed in code, a user must call `setup` to initialize the state before drawing. Each `blit_rect` call takes at least a rectangle, the area to draw to, and another texture, what to be drawn. The draw calls use a Texture_Blit Shader to process and calculate the result, pixel by pixel. Users can supply their own ShaderMaterial with custom Texture_Blit shaders for more complex behaviors.
	'''

  @staticmethod
  def constructor():
    class_ = DrawableTexture2D.construct_without_init()
    class_._ptr = constructor(280,0, ())
    return class_
  @staticmethod
  def new():
    class_ = DrawableTexture2D.construct_without_init()
    class_._ptr = constructor(280,0, ())
    return class_
  def __init__(self):
    self._ptr =  CPPDrawableTexture2DWrapper()
    self.casted_from = None
    if c_utils.shouldCreateObject:
      self._ptr = constructor(280,0, ())


  def generate_wrapper(self):
    return CPPDrawableTexture2DWrapper()
  def init_signals(self):
    super().init_signals()

  @staticmethod
  def construct_without_init():
    cls = DrawableTexture2D.__new__(DrawableTexture2D)
    cls.shouldBeDeleted = True
    cls.casted_from = None
    cls.constructed_from_python = False
    cls.init_signals()
    return cls
  @staticmethod
  def get_type():
    return 'DrawableTexture2D'

  def __del__(self):
    if self.casted_from is None:
      self._ptr.call_with_return(108, ())
      self._ptr = None
  @staticmethod
  def cast(other:'Object'):
    assert other != None # Object to be casted must not be None
    cls = DrawableTexture2D.construct_without_init()
    cls._ptr = CPPDrawableTexture2DWrapper()
    cls._ptr_before = other._ptr # Save pointer
    cls._ptr.copy_gdowner(cls._ptr_before)
    cls.casted_from = other
    return cls
  @staticmethod
  def cast_without_reference(other: 'Object'):
    assert other != None # Object to be casted must not be None
    cls = DrawableTexture2D.construct_without_init()
    cls._ptr = CPPDrawableTexture2DWrapper()
    cls._ptr_before = other._ptr # Save pointer
    cls._ptr.copy_gdowner(cls._ptr_before)
    return cls

  @functools.native_method
  def set_format(self, format:'int'  ) -> None:
    r'''
				Sets the format of this DrawableTexture.
			'''

    assert isinstance(format, (int, float)), 'format must be int or float'







    self._ptr.call_with_return(101,tuple([format]))

  @functools.native_method
  def set_use_mipmaps(self, mipmaps:'bool'   ) -> None:
    r'''
				Sets if mipmaps should be used on this DrawableTexture.
			'''

    assert isinstance(mipmaps, bool), 'mipmaps must be bool'







    self._ptr.call_with_return(102,tuple([mipmaps]))

  @functools.native_method
  def get_use_mipmaps(self) -> bool:
    r'''
				Returns `true` if mipmaps are set to be used on this DrawableTexture.
			'''




    _ret = 0
    _ret = self._ptr.call_with_return(103,tuple([]))
    return _ret


  @functools.native_method
  def setup(self, width:'int'   , height:'int'   , format:'int'  , color:'Color' = None  , use_mipmaps:'bool' =False  ) -> None:
    r'''
				Initializes the DrawableTexture to a White texture of the given `width`, `height`, and `format`.
			'''
    if color is None:
      color = Color.new0()

    assert isinstance(width, (int, float)), 'width must be int or float'
    assert isinstance(height, (int, float)), 'height must be int or float'
    assert isinstance(format, (int, float)), 'format must be int or float'
    assert isinstance(use_mipmaps, bool), 'use_mipmaps must be bool'











    self._ptr.call_with_return(104,tuple([width, height, format, color._ptr, use_mipmaps]))

  @functools.native_method
  def blit_rect(self, rect:'Rect2i'   , source:'py4godot_texture2d.Texture2D'   , modulate:'Color' = None  , mipmap:'int' =0  , material:'py4godot_material.Material' = None  ) -> None:
    r'''
				Draws to given `rect` on this texture by copying from the given `source`. A `modulate` color can be passed in for the shader to use, but defaults to White. The `mipmap` value can specify a draw to a lower mipmap level. The `material` parameter can take a ShaderMaterial with a TextureBlit Shader for custom drawing behavior.
			'''
    if modulate is None:
      modulate = Color.new0()
    if material is None:
      material = c_utils.empty_object

    assert(not rect is None)
    assert isinstance(rect, Rect2i), 'rect must be Rect2i'
    assert(not source is None)
    assert isinstance(source, get_class('Texture2D')), 'source must be Texture2D'
    assert isinstance(mipmap, (int, float)), 'mipmap must be int or float'











    self._ptr.call_with_return(105,tuple([rect._ptr, source._ptr, modulate._ptr, mipmap, material._ptr]))

  @functools.native_method
  def blit_rect_multi(self, rect:'Rect2i'   , sources:'py4godot_texture2dtypedarray.Texture2DTypedArray'   , extra_targets:'py4godot_drawabletexture2dtypedarray.DrawableTexture2DTypedArray'   , modulate:'Color' = None  , mipmap:'int' =0  , material:'py4godot_material.Material' = None  ) -> None:
    r'''
				Draws to the given `rect` on this texture, as well as on up to 3 DrawableTexture `extra_targets`. All `extra_targets` must be the same size and DrawableFormat as the original target, otherwise the Shader may fail. Expects up to 4 Texture `sources`, but will replace missing `sources` with default Black Textures.
			'''
    if modulate is None:
      modulate = Color.new0()
    if material is None:
      material = c_utils.empty_object

    assert(not rect is None)
    assert isinstance(rect, Rect2i), 'rect must be Rect2i'
    assert isinstance(sources, Array), 'sources must be Array'
    assert isinstance(extra_targets, Array), 'extra_targets must be Array'
    assert isinstance(mipmap, (int, float)), 'mipmap must be int or float'












    self._ptr.call_with_return(106,tuple([rect._ptr, sources._ptr, extra_targets._ptr, modulate._ptr, mipmap, material._ptr]))

  @functools.native_method
  def generate_mipmaps(self) -> None:
    r'''
				Re-calculates the mipmaps for this texture on demand.
			'''




    self._ptr.call_with_return(107,tuple([]))


register_cast_function('DrawableTexture2D', DrawableTexture2D.cast)
register_class('DrawableTexture2D', DrawableTexture2D)
